import { createHash } from 'node:crypto'
import { envFlag } from '@/lib/env/string'
import type { SiteLook } from '@/lib/theme/site-style'
import { siteSkinCss, type SiteSkinName } from './site-skin-css'

export function themeStylesheetName(css: string): string {
  return createHash('sha256').update(css).digest('hex').slice(0, 24) + '.css'
}

export function siteThemeStylesheet(theme: SiteSkinName | undefined, look: Partial<SiteLook>): string | undefined {
  // The pilot requires a built preview with assets generated by prebuild. Production stays inline.
  if (process.env.NODE_ENV !== 'production' || process.env.VERCEL_ENV === 'production' || !envFlag('SITE_THEME_STYLESHEET_PILOT')) return undefined
  return '/_site-theme-assets/' + themeStylesheetName(siteSkinCss(theme, look))
}
